+      if (auto err = out_img->add_channel(heif_channel_G, width, height, output_sample_bits(get_bits_per_pixel(heif_channel_G)), limits)) {
         return err;
       }
-      if (auto err = out_img->add_channel(heif_channel_B, width, height, get_bits_per_pixel(heif_channel_B), limits)) {
