         return err;
       }
-      if (auto err = out_img->add_channel(heif_channel_Cb, cw, ch, get_bits_per_pixel(heif_channel_Cb), limits)) {
+      if (auto err = out_img->add_channel(heif_channel_Cb, cw, ch, output_sample_bits(get_bits_per_pixel(heif_channel_Cb)), limits)) {
         return err;
       }
-      if (auto err = out_img->add_channel(heif_channel_Cr, cw, ch, get_bits_per_pixel(heif_channel_Cr), limits)) {
+      if (auto err = out_img->add_channel(heif_channel_Cr, cw, ch, output_sample_bits(get_bits_per_pixel(heif_channel_Cr)), limits)) {
         return err;
       }
     }
